        // 枚举合成因子 w，w>=2 且不能是完全平方数
        int maxW = n / i;
        for (int w = 2; w <= maxW; ++w) {
            if (!isSquare[w]) {
                dp[i * w] += dp[i];
            }
        }
    }

    return dp[n];
}

